// Shape of public/data/flood-replay.json (generated by scripts/gen-scenario.ts).

export type Lang = 'en' | 'hi' | 'pa';

/** Scripted farmer behaviour. Offsets are hours. */
export type Persona =
  | 'focus' // the judge plays this farmer
  | 'normal'
  | 'offline' // no signal: queued, syncs later
  | 'missed' // misses the 72 h window
  | 'nodamage' // replies "no damage" (false alarm)
  | 'assisted' // helper captures with recorded consent
  | 'partial' // incomplete evidence
  | 'slowack' // insurer acknowledgement slips -> escalation
  | 'noref' // files but never records a reference number
  | 'quiet'; // not alerted (monitoring only)

/** [persona, captureDelay, shots, geoOffsetM, syncDelay, fileDelay(-1 never), ackDelay(-1 never)] */
export type Behaviour = [Persona, number, number, number, number, number, number];

export interface PlotRaw {
  id: string;
  v: number; // village index
  pts: number[]; // flat x,y polygon in map units
  crop: string;
  name: string;
  lang: Lang;
  khasra: string;
  b: Behaviour;
  hailYes?: 1; // replies yes to the low-confidence hail prompt
  /** Relief rail, simulated: [hours after the officer publishes the draft list at which this farmer files an objection with sealed evidence, hours the officer then takes to respond (-1: not yet)]. */
  obj?: [number, number];
}

export interface StationRaw {
  id: string;
  name: string;
  x: number;
  y: number;
  rain: number[]; // hourly rainfall, tenths of a mm, length = hours + 1
}

export interface RiverGaugeRaw {
  id: string;
  name: string;
  kind: 'stage' | 'release';
  unit: string;
  x: number;
  y: number;
  /** one reading per hour, integers in `unit` */
  series: number[];
  /** danger level in the same unit: a scenario parameter, not an official level */
  danger: number;
}
export interface RiverRaw {
  gauges: RiverGaugeRaw[];
  /** plots within this distance of the river centre line are riverside */
  reachM: number;
  /** low-lying plots within this larger distance are also in reach */
  lowReachM: number;
  /** a gauge this far downstream of a plot still counts as adjacent */
  adjacentM: number;
  /** flood-wave travel speed from a gauge to a plot, km per hour */
  waveKmh: number;
  /** plots whose travel lag from the gauge is longer than this are out of reach */
  maxLagH: number;
  /** hours from a gauge reading to the rule being evaluated */
  latencyH: number;
}

export interface ScenarioRaw {
  v: 1;
  seed: number;
  name: string;
  district: string;
  block: string;
  t0: string; // ISO local time of T+0 (fictional)
  hours: number; // 168
  grid: { cols: number; rows: number; cell: number };
  map: {
    w: number;
    h: number;
    scaleM: number; // metres per map unit
    origin: [number, number]; // synthetic lat, lon of map (0,0)
    boundary: string;
    river: string;
    canal: string;
    roads: string[];
    villages: { name: string; x: number; y: number }[];
  };
  /** one base-36 char per cell, value*0.2 = metres above river; '.' = outside district */
  elev: string;
  /** two base-36 chars per cell: flood onset hour / recede hour; 'zz' = never */
  onset: string;
  recede: string;
  stations: StationRaw[];
  sar: number[]; // simulated SAR pass hours (the demo cadence)
  /** radar passes of the slower cadence, a few days apart (closer to real revisit times; still simulated) */
  sarSlow?: number[];
  /** crops that normally show standing water to radar in this season (paddy), and the share of the plot they show */
  baselineWet?: { crops: string[]; frac: number };
  /** river and dam gauges for Rule C, and how far their reach extends (all simulated) */
  river?: RiverRaw;
  thresholds: {
    rain24: number; // mm in 24 h ("heavy rain")
    rainHeavy: number; // mm in 24 h for the rain+terrain rule
    floodFrac: number; // SAR flooded share of plot to trigger
    clearFrac: number; // share considered "clear" at baseline
    damageFrac: number; // synthetic ground truth: share submerged
    damageHours: number; // ... for at least this many hours
    lowElev: number; // terrain class: low-lying below (m)
    midElev: number;
  };
  hail: { t: number; x: number; y: number; r: number };
  focus: string;
  /**
   * Helper mode: the farmers a helper (sarpanch, CSC operator, cooperative or extension worker) captures for on one phone.
   * Chosen by the generator from the demo farmer's village. Plot ids, in queue order.
   */
  helperQueue?: string[];
  plots: PlotRaw[];
}
